from pathlib import Path
from html import escape as esc
import json, os, shutil

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'public'
BASE=os.environ.get('SITE_URL','https://teoriadejuego.github.io').rstrip('/')
DATE='2026-11-16'
def data(n):return json.loads((ROOT/'data'/n).read_text(encoding='utf8'))
PUBS=data('publications.json'); PROJECTS=data('projects.json'); SOFTWARE=data('software.json'); WORKING=data('working-papers.json'); RESOURCES=data('resources.json')
OUT.mkdir(exist_ok=True)
shutil.copytree(ROOT/'assets',OUT/'assets',dirs_exist_ok=True)
pages=[]
def t(es,en,lang):return en if lang=='en' else es
def loc(v,lang):return v.get(lang,v.get('es','')) if isinstance(v,dict) else v
def route(lang,key=''):return ('en/' if lang=='en' else '')+key
def rel(current,target):
 return os.path.relpath(OUT/target, (OUT/current).parent).replace('\\','/') if target else os.path.relpath(OUT,(OUT/current).parent).replace('\\','/')+'/'
def link(url,label,cls=''):
 return f'<a href="{esc(url,quote=True)}"'+(f' class="{cls}"' if cls else '')+f'>{esc(label)}</a>'
def button(current,lang,key,label,style=''):return link(rel(current,route(lang,key)),label,'button '+style)
def network():
 pts=[(40,70),(88,26),(110,124),(165,65),(205,26),(224,132),(280,66),(324,121),(340,26),(170,165)]
 edges=[(0,1),(0,2),(1,3),(2,3),(2,9),(3,4),(3,5),(3,9),(4,6),(5,6),(5,7),(6,7),(6,8),(7,8)]
 s='<svg class="network" viewBox="0 0 380 190" aria-hidden="true">'
 for a,b in edges:s+=f'<line class="edge" x1="{pts[a][0]}" y1="{pts[a][1]}" x2="{pts[b][0]}" y2="{pts[b][1]}"/>'
 for i,(x,y) in enumerate(pts):s+=f'<circle class="node {"accent" if i==3 else ""}" cx="{x}" cy="{y}" r="{12 if i in [3,6] else 8}"/>'
 return s+'</svg>'
def visual(p,lang):
 id=p['id']
 if id=='networks':return network()
 if id=='pbis':
  labels=t(['Centro','Aulas','Estudiantes'],['School','Classes','Students'],lang)
  return f'<svg class="schematic" viewBox="0 0 380 190" aria-hidden="true"><path d="M190 48 V75 M85 75 H295 M85 75 V100 M295 75 V100 M85 130 V154 M295 130 V154"/><rect x="130" y="12" width="120" height="36" rx="4"/><rect x="25" y="95" width="120" height="36" rx="4"/><rect x="235" y="95" width="120" height="36" rx="4"/><text x="190" y="36">{labels[0]}</text><text x="85" y="119">{labels[1]}</text><text x="295" y="119">{labels[1]}</text><text x="85" y="179">{labels[2]}</text><text x="295" y="179">{labels[2]}</text></svg>'
 if id=='collective-action':
  labels=t(['Decisión','Solución común','Alternativa privada'],['Decision','Shared solution','Private alternative'],lang)
  return f'<svg class="schematic" viewBox="0 0 380 190" aria-hidden="true"><path d="M190 60 V92 M90 92 H290 M90 92 V120 M290 92 V120"/><circle cx="190" cy="35" r="24"/><rect x="5" y="118" width="170" height="47" rx="4"/><rect x="205" y="118" width="170" height="47" rx="4"/><text x="90" y="147">{labels[1]}</text><text x="290" y="147">{labels[2]}</text><text x="190" y="84">{labels[0]}</text></svg>'
 if id=='teenslab':
  labels=t(['Datos','Variables','Protocolo'],['Data','Variables','Protocol'],lang)
  return '<svg class="schematic" viewBox="0 0 380 190" aria-hidden="true">'+''.join(f'<rect x="{12+i*125}" y="20" width="110" height="115" rx="4"/><path d="M{29+i*125} 52 H{105+i*125} M{29+i*125} 76 H{105+i*125} M{29+i*125} 100 H{86+i*125}"/><text x="{67+i*125}" y="165">{label}</text>' for i,label in enumerate(labels))+'</svg>'
 labels={'sonar':t(['Protocolo','Experimento','Evidencia'],['Protocol','Experiment','Evidence'],lang),'arco':['SALMER','DOVELA','CLAVE'],'teenslab':t(['Medir','Documentar','Reutilizar'],['Measure','Document','Reuse'],lang)}
 return '<div class="pipeline" aria-hidden="true">'+''.join('<span>'+s+'</span>' for s in labels.get(id,[]))+'</div>'
def shell(lang,key,title,description,body,navkey='',extra_schema=None):
 current=route(lang,key+'index.html' if not key.endswith('.html') else key)
 counterpart=route('es' if lang=='en' else 'en',key)
 canon=BASE+'/'+route(lang,key)
 asset=lambda n:rel(current,'assets/'+n)
 nav_items=[('',t('Inicio','Home',lang)),('projects/',t('Proyectos','Projects',lang)),('publications/',t('Publicaciones','Publications',lang)),('profile/',t('Perfil','Profile',lang)),('lab/',t('Laboratorio','Lab',lang))]
 nav=''.join(f'<a href="{rel(current,route(lang,k))}"'+(' aria-current="page"' if k==navkey else '')+f'>{v}</a>' for k,v in nav_items)
 person={'@type':'Person','@id':BASE+'/#antonio-alfonso','name':'Antonio Alfonso','alternateName':['Antonio Alfonso Costillo','Antonio Alfonso-Costillo'],'url':BASE+'/','image':BASE+'/assets/portrait.webp','jobTitle':t('Profesor Ayudante Doctor e investigador','Assistant Professor and researcher',lang),'worksFor':{'@type':'Organization','name':'Universidad de Sevilla'},'sameAs':['https://orcid.org/0000-0002-5396-3711','https://scholar.google.com/citations?user=tplq8tMAAAAJ','https://github.com/Teoriadejuego','https://www.antonioalfonso.org/'],'knowsAbout':['Experimental economics','Data science','Experiment design','Network analysis','Data visualization']}
 schema={'@context':'https://schema.org','@type':'ProfilePage' if key in ['', 'profile/'] else 'WebPage','url':canon,'name':title,'inLanguage':lang,'dateModified':DATE,'mainEntity':person if key in ['', 'profile/'] else {'@id':BASE+'/#antonio-alfonso'}}
 schemas=[schema]+(extra_schema or [])
 html=f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description,quote=True)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="theme-color" content="#10263e"><link rel="canonical" href="{canon}"><link rel="alternate" hreflang="es" href="{BASE+'/'+route('es',key)}"><link rel="alternate" hreflang="en" href="{BASE+'/'+route('en',key)}"><link rel="alternate" hreflang="x-default" href="{BASE+'/'+route('es',key)}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{canon}"><meta property="og:image" content="{BASE}/assets/hero.webp"><meta property="og:locale" content="{'en_GB' if lang=='en' else 'es_ES'}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{asset('favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{asset('style.css')}"><script src="{asset('app.js')}" defer></script>{''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('</','<\\/')+'</script>' for s in schemas)}</head>
<body><a class="skip" href="#main">{t('Saltar al contenido','Skip to content',lang)}</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="{rel(current,route(lang,''))}">Antonio Alfonso<span>{t('Datos, experimentos y decisiones','Data, experiments and decisions',lang)}</span></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">{t('Menú','Menu',lang)}</button><nav class="nav" id="navigation" aria-label="{t('Navegación principal','Main navigation',lang)}">{nav}<a class="lang" lang="{'es' if lang=='en' else 'en'}" hreflang="{'es' if lang=='en' else 'en'}" href="{rel(current,counterpart)}">{'Español' if lang=='en' else 'English'}</a></nav></div></header><main id="main">{body}</main><footer class="footer"><div class="wrap footer-inner"><div><p>© 2026 Antonio Alfonso Costillo</p><p>{t('Sevilla · Actualizado el 16 de noviembre de 2026','Seville · Updated 16 November 2026',lang)}</p></div><div class="footer-links">{link('https://github.com/Teoriadejuego','GitHub')}{link('https://orcid.org/0000-0002-5396-3711','ORCID')}{link('https://scholar.google.com/citations?user=tplq8tMAAAAJ','Google Scholar')}{link(rel(current,route(lang,'privacy/')),t('Privacidad y créditos','Privacy and credits',lang))}</div></div></footer></body></html>'''
 path=OUT/current;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(html,encoding='utf8');pages.append(canon)

def contact(lang,current):
 return f'''<section class="section dark" id="contact"><div class="wrap contact-panel"><div><h2>{t('¿Tu equipo necesita conectar datos y decisiones?','Does your team need to connect data and decisions?',lang)}</h2><p>{t('Me interesan oportunidades en consultoría tecnológica, ciencia de datos aplicada y experimentación. Hablemos del problema, del equipo y de la evidencia que necesitáis.','I am interested in opportunities in technology consulting, applied data science and experimentation. Let’s discuss the problem, the team and the evidence you need.',lang)}</p></div><div><a class="contact-link" href="mailto:aalfonsoc@gmail.com">aalfonsoc@gmail.com</a><p>{t('Sevilla, España','Seville, Spain',lang)}</p>{button(current,lang,'profile/',t('Consultar mi perfil','View my profile',lang),'light')}</div></div></section>'''

def work_card(p,lang,current):
 return f'''<article class="work" data-kind="{p['kind']}"><div class="visual">{visual(p,lang)}</div><p class="work-type">{t('Software y herramientas','Software and tools',lang) if p['kind']=='software' else t('Investigación publicada','Published research',lang)}</p><p class="meta">{esc(loc(p['status'],lang))}</p><h3>{link(rel(current,route(lang,'projects/'+p['id']+'/')),loc(p['title'],lang))}</h3><p class="summary">{esc(loc(p['summary'],lang))}</p><div class="tags">{''.join('<span class="tag">'+esc(s)+'</span>' for s in p['tags'])}</div>{link(rel(current,route(lang,'projects/'+p['id']+'/')),t('Ver el caso →','Explore the case →',lang),'link')}</article>'''

def home(lang):
 c=route(lang,'index.html')
 selected=[PUBS[i] for i in [1,8,4,9]]
 research=''.join(f'''<article class="research-row"><span class="journal">{esc(p['journal'])} · {p['year']}</span><h3>{link(rel(c,route(lang,'publications/'))+'#'+p['id'],p['title'])}</h3><p>{esc(p['summary'][lang])}</p>{link(rel(c,route(lang,'publications/'))+'#'+p['id'],t('Artículo y acceso abierto →','Article and open access →',lang))}</article>''' for p in selected)
 body=f'''<section class="hero"><div class="wrap hero-inner"><div><p class="intro">{t('Antonio Alfonso · Economista experimental, PhD','Antonio Alfonso · Experimental economist, PhD',lang)}</p><h1>{t('Experimentos, datos y software para decidir mejor.','Experiments, data and software for better decisions.',lang)}</h1><p class="lead">{t('Conecto ciencia del comportamiento, análisis de datos y desarrollo de herramientas. Del diseño de una pregunta a una evidencia que un equipo pueda utilizar.','I connect behavioural science, data analysis and tool development. From a well-designed question to evidence a team can use.',lang)}</p><div class="actions">{button(c,lang,'projects/',t('Explorar proyectos','Explore projects',lang),'light')}{link('mailto:aalfonsoc@gmail.com',t('Hablemos','Let’s talk',lang),'button outline')}</div><p class="fine">{t('Interesado en oportunidades en consultoras tecnológicas y equipos de datos.','Interested in opportunities with technology consultancies and data teams.',lang)}</p></div><div class="portrait"><figure><img src="{rel(c,'assets/portrait-800.webp')}" srcset="{rel(c,'assets/portrait-400.webp')} 400w, {rel(c,'assets/portrait-800.webp')} 800w, {rel(c,'assets/portrait.webp')} 1254w" sizes="(max-width:760px) 140px, 310px" width="1254" height="1254" alt="Antonio Alfonso" fetchpriority="high"><figcaption>{t('Profesor Ayudante Doctor<br>Universidad de Sevilla','Assistant Professor<br>University of Seville',lang)}</figcaption></figure></div></div></section>
<div class="proof"><div class="wrap proof-inner"><a href="{rel(c,route(lang,'publications/'))}"><strong>{t('Investigación contrastable','Research you can inspect',lang)}</strong><p>PNAS · Scientific Data · Economics Letters</p></a><a href="{rel(c,route(lang,'projects/'))}"><strong>{t('Herramientas que se pueden explorar','Tools you can explore',lang)}</strong><p>SONAR · ARCO · PBIS</p></a><a href="{rel(c,route(lang,'profile/'))}"><strong>{t('Del método a la implementación','From method to implementation',lang)}</strong><p>Python · R · JavaScript</p></a></div></div>
<section class="section"><div class="wrap"><div class="section-head"><h2>{t('Trabajo que puedes explorar.','Work you can explore.',lang)}</h2><p>{t('Proyectos que conectan investigación, software y uso real de la información. Cada caso explica su alcance y tu acceso a la evidencia.','Projects connecting research, software and practical use of information. Each case explains its scope and links to the evidence.',lang)}</p></div><div class="work-grid">{''.join(work_card(p,lang,c) for p in PROJECTS[:3])}</div><div class="actions">{button(c,lang,'projects/',t('Todos los proyectos y casos','All projects and case studies',lang),'outline')}</div></div></section>
<section class="section tint"><div class="wrap"><div class="section-head"><h2>{t('Qué puedo aportar a tu equipo.','What I can bring to your team.',lang)}</h2></div><div class="capabilities"><div><h3>{t('Diseñar una evaluación útil','Design a useful evaluation',lang)}</h3><p>{t('Convertir una pregunta de producto o de política en hipótesis, tratamientos y medidas. Pensar en asignación, calidad de respuesta y límites de interpretación desde el principio.','Turn a product or policy question into hypotheses, treatments and measures. Consider assignment, response quality and interpretation limits from the start.',lang)}</p></div><div><h3>{t('Hacer los datos utilizables','Make data usable',lang)}</h3><p>{t('Conectar recogida, validación, análisis y documentación. Construir recorridos reproducibles que permitan comprobar de dónde sale cada resultado.','Connect collection, validation, analysis and documentation. Build reproducible workflows that make the origin of each result inspectable.',lang)}</p></div><div><h3>{t('Construir para quien decide','Build for decision-makers',lang)}</h3><p>{t('Traducir modelos e indicadores en herramientas visuales. Diseñar interfaces que permitan explorar contexto, datos pendientes y diferencias relevantes.','Translate models and indicators into visual tools. Design interfaces for exploring context, missing data and meaningful differences.',lang)}</p></div></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><h2>{t('Una base científica sólida.','A strong scientific foundation.',lang)}</h2>{link(rel(c,route(lang,'publications/')),t('Todos los artículos y descargas →','All articles and downloads →',lang))}</div><p class="muted">{t('Selección por alcance, método y relevancia para problemas aplicados. Resultados de estudios en coautoría; no métricas comerciales.','Selected for scope, method and relevance to applied problems. Findings from co-authored studies, not commercial performance metrics.',lang)}</p><div class="research-list">{research}</div></div></section>
<section class="section tint"><div class="wrap split"><div><h2>{t('Rigor que se puede explicar.','Rigour that can be explained.',lang)}</h2><p class="lead">{t('La diferencia entre un resultado prometedor y una decisión defendible está en cómo se ha obtenido la evidencia.','The difference between a promising result and a defensible decision lies in how the evidence was obtained.',lang)}</p></div><div><h3>{t('Prueba el laboratorio de incertidumbre','Try the uncertainty lab',lang)}</h3><p>{t('Explora cómo el tamaño de la muestra y la variabilidad cambian la precisión de una comparación. Una demostración interactiva, con supuestos explícitos y sin datos personales.','Explore how sample size and variability affect the precision of a comparison. An interactive demonstration with explicit assumptions and no personal data.',lang)}</p>{button(c,lang,'lab/',t('Explorar la demostración','Explore the demonstration',lang),'outline')}</div></div></section>'''+contact(lang,c)
 shell(lang,'',t('Antonio Alfonso | Ciencia de datos, experimentación y consultoría tecnológica','Antonio Alfonso | Data science, experimentation and technology consulting',lang),t('Economista experimental y profesor de la Universidad de Sevilla. Proyectos en Python, R y JavaScript, visualización de datos, investigación y evaluación de impacto.','Experimental economist and University of Seville researcher. Python, R and JavaScript projects, data visualisation, research and impact evaluation.',lang),body)

def publication_page(lang):
 c=route(lang,'publications/index.html');entries=[];schemas=[]
 for p in PUBS:
  authors=p['authors'];short='; '.join(authors if len(authors)<10 else authors[:6])+(' et al.' if len(authors)>=10 else '')
  authorhtml=esc(short)
  for name in ['Antonio Alfonso-Costillo','Antonio Alfonso','A. Alfonso']:
   if name in short:authorhtml=authorhtml.replace(esc(name),'<strong>'+esc(name)+'</strong>',1);break
  venue=f"{p['journal']} · {p['year']}"+(f" · {p['volume']}" if p['volume'] else '')
  actions=[link('https://doi.org/'+p['doi'],'DOI')]+[link(a['url'],loc(a['label'],lang)) for a in p['links']]
  entries.append(f'''<article class="publication" id="{p['id']}" data-search="{esc(p['doi'])}" data-topic="{p['topic']}" data-year="{p['year']}"><div class="year">{p['year']}</div><div><h2>{link('https://doi.org/'+p['doi'],p['title'])}</h2><p class="authors">{authorhtml}</p><p class="venue">{esc(venue)}</p><p class="summary">{esc(p['summary'][lang])}</p><div class="pub-links">{''.join(actions)}</div>{'<p class="version">'+esc(loc(p['version'],lang))+'</p>' if p.get('version') else ''}</div></article>''')
  schemas.append({'@context':'https://schema.org','@type':'ScholarlyArticle','name':p['title'],'identifier':p['doi'],'url':'https://doi.org/'+p['doi'],'author':[{'@type':'Person','name':a} for a in authors],'isPartOf':{'@type':'Periodical','name':p['journal']}})
 opts=[('experiments',t('Experimentos','Experiments',lang)),('networks',t('Redes','Networks',lang)),('data',t('Datos abiertos','Open data',lang)),('behavior',t('Comportamiento','Behaviour',lang))]
 working=''.join(f'''<article class="research-row"><p class="status-label">{loc(w['status'],lang)} · {w['year']}</p><h3>{link(w['url'],w['title'])}</h3><p class="small">{esc(w['authors'])}</p>{link(w['pdf'],t('Descargar PDF · Loyola','Download PDF · Loyola',lang)) if w.get('pdf') else ''}</article>''' for w in WORKING)
 body=f'''<section class="page-heading"><div class="wrap"><h1>{t('Publicaciones y acceso abierto.','Publications and open access.',lang)}</h1><p class="lead">{t('La evidencia detrás del perfil: artículos, documentos de trabajo y versiones abiertas para leer, descargar y contrastar.','The evidence behind the profile: articles, working papers and open versions to read, download and examine.',lang)}</p><p class="small">{t('12 artículos, incluido uno disponible online y asignado al número de diciembre de 2026. Los preprints se listan por separado.','12 articles, including one available online and assigned to the December 2026 issue. Preprints are listed separately.',lang)}</p><div class="actions">{link(rel(c,'downloads/publications.bib'),t('Descargar bibliografía · BibTeX','Download bibliography · BibTeX',lang),'button outline')}{link('https://scholar.google.com/citations?user=tplq8tMAAAAJ','Google Scholar')}</div></div></section><section class="section"><div class="wrap"><div class="filters"><div><label for="pub-search">{t('Buscar por título, autor o tema','Search by title, author or topic',lang)}</label><input id="pub-search" type="search" autocomplete="off" placeholder="{t('Por ejemplo: redes, honesty, PNAS','For example: networks, honesty, PNAS',lang)}"></div><div><label for="pub-topic">{t('Tema','Topic',lang)}</label><select id="pub-topic"><option value="">{t('Todos los temas','All topics',lang)}</option>{''.join('<option value="'+k+'">'+v+'</option>' for k,v in opts)}</select></div><div><label for="pub-year">{t('Año','Year',lang)}</label><select id="pub-year"><option value="">{t('Todos los años','All years',lang)}</option>{''.join(f'<option value="{y}">{y}</option>' for y in range(2026,2020,-1))}</select></div></div><p class="count" id="pub-count" role="status" aria-live="polite"></p><noscript><p class="no-js">{t('La lista completa está disponible. Los filtros requieren JavaScript.','The complete list is available. Filters require JavaScript.',lang)}</p></noscript>{''.join(entries)}<p class="empty" id="pub-empty" hidden>{t('No hay resultados. Prueba otro término o elimina los filtros.','No matches. Try another term or clear the filters.',lang)}</p></div></section><section class="section tint"><div class="wrap"><h2>{t('Documentos de trabajo.','Working papers.',lang)}</h2><p>{t('Trabajos en desarrollo; se distinguen de las publicaciones evaluadas por pares.','Work in progress, distinguished from peer-reviewed publications.',lang)}</p><div class="research-list">{working}</div><p class="small">{t('Reading Minds to Win continúa el trabajo anteriormente titulado The development of rationality in games with hidden information.','Reading Minds to Win continues the work previously titled The development of rationality in games with hidden information.',lang)}</p></div></section><section class="section"><div class="wrap narrow"><h2>{t('Cómo consultar las versiones.','How to use the versions.',lang)}</h2><p>{t('El DOI identifica el artículo editorial. Los botones de repositorio llevan a una ficha institucional o a un archivo abierto; cuando es un manuscrito previo, se indica. Las descargas se sirven desde su institución o editor, que conserva sus condiciones de acceso y licencia.','The DOI identifies the published article. Repository buttons lead to an institutional record or an open file; earlier manuscripts are labelled. Downloads are served by the institution or publisher under their own access and licence conditions.',lang)}</p></div></section>'''
 shell(lang,'publications/',t('Publicaciones de Antonio Alfonso | Artículos y descargas abiertas','Antonio Alfonso publications | Articles and open downloads',lang),t('Todos los artículos de Antonio Alfonso en PNAS, Scientific Data, Economics Letters y otras revistas, con DOI, repositorios y acceso abierto.','Antonio Alfonso’s articles in PNAS, Scientific Data, Economics Letters and other journals, with DOI links, repositories and open access.',lang),body,'publications/',schemas)

def projects_page(lang):
 c=route(lang,'projects/index.html')
 soft=''.join(f'''<article><p class="status-label">{loc(p['stage'],lang)}</p><h3>{esc(loc(p['title'],lang))}</h3><p>{esc(loc(p['description'],lang))}</p><div class="pub-links">{link('https://github.com/Teoriadejuego/'+p['repo'],t('Ver repositorio','View repository',lang))}{link(p['demo'],t('Abrir demostración','Open demonstration',lang)) if p.get('demo') else ''}</div></article>''' for p in SOFTWARE)
 body=f'''<section class="page-heading"><div class="wrap"><h1>{t('De la pregunta a la herramienta.','From question to tool.',lang)}</h1><p class="lead">{t('Software, experimentos y datos que muestran cómo trabajo. Casos seleccionados con fuentes, código o demostraciones para explorar.','Software, experiments and data that show how I work. Selected cases with sources, code or demonstrations to explore.',lang)}</p></div></section><section class="section project-index"><div class="wrap"><div class="work-grid">{''.join(work_card(p,lang,c) for p in PROJECTS)}</div></div></section><section class="section tint"><div class="wrap"><h2>{t('Más herramientas y materiales abiertos.','More open tools and materials.',lang)}</h2><div class="software-list">{soft}</div><div class="actions">{link('https://github.com/Teoriadejuego?tab=repositories',t('Consultar todos los repositorios','Browse all repositories',lang),'button outline')}</div></div></section><section class="section"><div class="wrap split"><div><h2>{t('Investigación y transferencia.','Research and knowledge transfer.',lang)}</h2><p>{t('Participación en proyectos competitivos y colaboraciones de economía experimental, educación y evaluación. Las funciones de dirección se indican únicamente cuando están acreditadas.','Participation in competitive projects and collaborations in experimental economics, education and evaluation. Leadership roles are identified only where documented.',lang)}</p>{link('https://investigacion.us.es/sisius/sis_showpub.php?idpers=45496',t('Perfil institucional · Universidad de Sevilla','Institutional profile · University of Seville',lang))}</div><div><ul class="text-list"><li><strong>SONAR (2026).</strong> {t('Investigador responsable; FIUS–Fundación Cotec.','Principal investigator; FIUS–Fundación Cotec.',lang)}</li><li><strong>DENT, ENCON, Between & Within.</strong> {t('Participación en equipos de investigación y trabajo sobre decisiones, educación, redes y comportamiento.','Participation in research and project teams studying decisions, education, networks and behaviour.',lang)}</li><li><strong>OutLabExp, AACID, GLOBE.</strong> {t('Experimentos fuera del laboratorio, cooperación para el desarrollo y colaboración científica.','Experiments outside the lab, development cooperation and scientific collaboration.',lang)}</li><li><strong>I Smart Prompts Hackathon (2024/25).</strong> {t('Dirección de un proyecto de innovación docente.','Leadership of a teaching-innovation project.',lang)}</li></ul>{link('https://loyolabehlab.org/members/antonio-alfonso/',t('Relación de proyectos · Loyola Behavioral Lab','Project record · Loyola Behavioral Lab',lang))}</div></div></section>'''+contact(lang,c)
 shell(lang,'projects/',t('Proyectos de Antonio Alfonso | Software, datos y experimentos','Antonio Alfonso projects | Software, data and experiments',lang),t('Explora SONAR, ARCO, PBIS y casos de investigación aplicada: experimentación digital, visualización de redes y datos reproducibles.','Explore SONAR, ARCO, PBIS and applied research cases: digital experimentation, network visualisation and reproducible data.',lang),body,'projects/')

def case_page(p,lang):
 key='projects/'+p['id']+'/';c=route(lang,key+'index.html')
 links=[]
 if p.get('repo'):links.append(link('https://github.com/Teoriadejuego/'+p['repo'],t('Consultar el código','Inspect the code',lang),'button'))
 if p.get('demo'):links.append(link(p['demo'],t('Explorar la demo','Explore the demo',lang),'button outline'))
 pub=next((a for a in PUBS if a['doi']==p.get('doi')),None)
 if pub:
  links.append(link('https://doi.org/'+p['doi'],t('Leer el artículo','Read the article',lang),'button'))
  links.append(link(rel(c,route(lang,'publications/'))+'#'+pub['id'],t('Repositorio y descarga','Repository and download',lang),'button outline'))
 source=p.get('source') or ('https://github.com/Teoriadejuego/'+p['repo'] if p.get('repo') else 'https://doi.org/'+p['doi'])
 body=f'''<section class="page-heading"><div class="wrap"><p class="breadcrumb">{link(rel(c,route(lang,'projects/')),t('← Todos los proyectos','← All projects',lang))}</p><div class="case-top"><div><p class="meta">{esc(loc(p['title'],lang))} · {esc(loc(p['status'],lang))}</p><h1>{esc(loc(p['heading'],lang))}</h1><p class="lead">{esc(loc(p['summary'],lang))}</p></div><div class="visual">{visual(p,lang)}</div></div></div></section><section class="section"><div class="wrap case-body"><aside class="case-aside"><h3>{t('Mi participación','My involvement',lang)}</h3><p>{esc(loc(p['role'],lang))}</p><div class="tags">{''.join('<span class="tag">'+esc(s)+'</span>' for s in p['tags'])}</div>{link(source,t('Fuente del caso ↗','Case source ↗',lang))}</aside><div><h2>{t('El problema','The problem',lang)}</h2><p>{esc(loc(p['problem'],lang))}</p><h2>{t('El trabajo','The work',lang)}</h2><p>{esc(loc(p['work'],lang))}</p><h2>{t('La evidencia disponible','Available evidence',lang)}</h2><p>{esc(loc(p['evidence'],lang))}</p><div class="callout"><h3>{t('Por qué es relevante para una empresa','Why it matters to a company',lang)}</h3><p>{esc(loc(p['value'],lang))}</p></div><div class="actions">{''.join(links)}</div><p class="small muted">{t('Los esquemas de esta página ilustran el enfoque; no representan datos individuales ni resultados adicionales del estudio.','The diagrams illustrate the approach; they do not represent individual data or additional study results.',lang)}</p></div></div></section>'''+contact(lang,c)
 shell(lang,key,loc(p['title'],lang)+' | Antonio Alfonso',loc(p['summary'],lang),body,'projects/')

def profile(lang):
 c=route(lang,'profile/index.html')
 jobs=[('2025–',t('Profesor Ayudante Doctor · Universidad de Sevilla','Assistant Professor · University of Seville',lang),t('Departamento de Economía Aplicada I. Docencia en Estadística e investigación.','Department of Applied Economics I. Statistics teaching and research.',lang)),('2020–2025','Universidad Loyola Andalucía',t('Ayudante de investigación, profesor asistente, ayudante doctor y profesor adjunto, en periodos sucesivos.','Successive research and faculty appointments, including Profesor Asistente, Ayudante Doctor and Adjunto.',lang)),('2019–2020','Universidad Pablo de Olavide',t('Profesor sustituto interino de Economía.','Temporary lecturer in Economics.',lang)),('2018–2019','Universidad Pablo de Olavide',t('Trabajo técnico de investigación y análisis de datos en Ciencias Experimentales.','Research technical work and data analysis in Experimental Sciences.',lang))]
 edu=[('2022',t('Doctor en Administración y Dirección de Empresas','PhD in Business Administration',lang),'Universidad Pablo de Olavide. '+t('Cum laude y mención internacional. Tesis sobre economía del comportamiento.','Cum laude and International Doctorate distinction. Thesis on behavioural economics.',lang)),('2020',t('Máster en Profesorado','Master’s in Teacher Education',lang),'Universidad Pablo de Olavide'),('2017',t('Máster en Economía Cuantitativa','MSc in Quantitative Economics',lang),'Universidad de Alicante'),('2015',t('Grado en Análisis Económico','Bachelor’s in Economic Analysis',lang),'Universidad Pablo de Olavide'),('2010',t('Grado en Ingeniería de la Edificación','Bachelor’s in Building Engineering',lang),'Universidad de Sevilla')]
 timeline=lambda rows:'<ul class="timeline">'+''.join(f'<li><time>{y}</time><div><p><strong>{esc(title)}</strong></p><small>{esc(desc)}</small></div></li>' for y,title,desc in rows)+'</ul>'
 body=f'''<section class="page-heading"><div class="wrap profile-top"><div><h1>Antonio Alfonso</h1><p class="lead">{t('Economista experimental con un perfil que combina investigación, programación y comunicación de resultados.','Experimental economist combining research, programming and communication of results.',lang)}</p><p>{t('Busco aportar esta combinación a consultoras tecnológicas y equipos de datos que necesiten diseñar evaluaciones, desarrollar herramientas y convertir información en decisiones fundamentadas.','I want to bring this combination to technology consultancies and data teams that need to design evaluations, develop tools and turn information into well-founded decisions.',lang)}</p><div class="actions">{link('mailto:aalfonsoc@gmail.com',t('Contactar','Contact me',lang),'button')}<button class="button outline print-button">{t('Imprimir / guardar perfil en PDF','Print / save profile as PDF',lang)}</button></div><p class="small">Antonio Alfonso Costillo · Sevilla · aalfonsoc@gmail.com</p></div><img src="{rel(c,'assets/portrait-400.webp')}" srcset="{rel(c,'assets/portrait-400.webp')} 400w, {rel(c,'assets/portrait-800.webp')} 800w" sizes="(max-width:760px) 180px, 270px" alt="Antonio Alfonso" width="1254" height="1254"></div></section><section class="section"><div class="wrap split"><div><h2>{t('Trayectoria','Experience',lang)}</h2>{timeline(jobs)}</div><div><h2>{t('Formación','Education',lang)}</h2>{timeline(edu)}</div></div></section><section class="section tint"><div class="wrap"><h2>{t('Cómo se traduce mi experiencia.','How my experience translates.',lang)}</h2><div class="principles"><div><h3>{t('Diseño y análisis','Design and analysis',lang)}</h3><p>{t('Experimentos de laboratorio, online y de campo; medición del comportamiento; inferencia estadística y análisis de redes.','Laboratory, online and field experiments; behavioural measurement; statistical inference and network analysis.',lang)}</p></div><div><h3>{t('Implementación','Implementation',lang)}</h3><p>Python, R, JavaScript, HTML, Stata, oTree, LimeSurvey, Qualtrics. {t('Proyectos públicos con React, FastAPI, Streamlit, Shiny y Quarto.','Public projects using React, FastAPI, Streamlit, Shiny and Quarto.',lang)}</p></div><div><h3>{t('Comunicación y formación','Communication and training',lang)}</h3><p>{t('Docencia de grado y posgrado, formación en programación y análisis experimental, dirección de proyectos docentes y codirección doctoral.','Undergraduate and postgraduate teaching, programming and experimental-analysis training, teaching-project leadership and doctoral co-supervision.',lang)}</p></div></div></div></section><section class="section"><div class="wrap split"><div><h2>{t('Colaboración internacional','International collaboration',lang)}</h2><ul class="text-list"><li><strong>University of Minnesota Morris · 2022.</strong> {t('Estancia de investigación de enero a julio.','Research stay from January to July.',lang)}</li><li><strong>Ateneo de Manila University · 2024.</strong> {t('Estancia de cuatro meses, de junio a octubre.','Four-month stay, June to October.',lang)}</li><li><strong>UCA, El Salvador · 2024.</strong> {t('Movilidad docente Erasmus.','Erasmus teaching mobility.',lang)}</li></ul></div><div><h2>{t('Reconocimiento y servicio','Recognition and service',lang)}</h2><ul class="text-list"><li>{t('Sexenio de investigación 2018–2023 reconocido por CNEAI y convalidado en la Universidad de Sevilla en 2026.','CNEAI-recognised research period 2018–2023, validated by the University of Seville in 2026.',lang)}</li><li>{t('Revisor para Journal of Behavioral and Experimental Economics, Nature Human Behaviour y PLOS ONE.','Reviewer for Journal of Behavioral and Experimental Economics, Nature Human Behaviour and PLOS ONE.',lang)}</li><li>{t('Codirección de la tesis de Gladis Herminia Gonzales Aguilar, defendida en 2025 con cum laude.','Co-supervision of Gladis Herminia Gonzales Aguilar’s PhD, defended in 2025 with cum laude.',lang)}</li></ul></div></div></section>'''+contact(lang,c)
 shell(lang,'profile/',t('Perfil de Antonio Alfonso | Datos, experimentación y desarrollo','Antonio Alfonso profile | Data, experimentation and development',lang),t('Trayectoria, formación y capacidades de Antonio Alfonso Costillo. Profesor de la Universidad de Sevilla, economista experimental y desarrollador de herramientas de datos.','Experience, education and capabilities of Antonio Alfonso Costillo. University of Seville researcher, experimental economist and data-tool developer.',lang),body,'profile/')

def lab_page(lang):
 c=route(lang,'lab/index.html')
 resources=''.join('<li>'+link(r['url'],r['title'])+(link(r['pdf'],t('Descargar material · Loyola','Download material · Loyola',lang),'small') if r.get('pdf') else '')+'</li>' for r in RESOURCES)
 body=f'''<section class="page-heading"><div class="wrap"><h1>{t('Hacer visible la incertidumbre.','Make uncertainty visible.',lang)}</h1><p class="lead">{t('Una demostración sencilla de por qué un cambio observado no basta para tomar una decisión. Ajusta los supuestos y observa la precisión de la estimación.','A simple demonstration of why an observed change is not enough to make a decision. Adjust the assumptions and see how the precision changes.',lang)}</p></div></section><section class="section"><div class="wrap"><p class="demo-note">{t('Ejemplo ilustrativo con valores sintéticos. No analiza datos reales ni calcula la potencia de un experimento.','Illustrative example with synthetic values. It does not analyse real data or calculate experimental power.',lang)}</p><div class="lab" id="experiment-lab"><div><div class="control"><label for="sample">{t('Observaciones por grupo','Observations per group',lang)}: <output id="sample-value" for="sample">200</output></label><input id="sample" type="range" min="20" max="2000" step="20" value="200"></div><div class="control"><label for="effect">{t('Diferencia observada (puntos)','Observed difference (points)',lang)}: <output id="effect-value" for="effect">3</output></label><input id="effect" type="range" min="0" max="15" step="0.5" value="3"></div><div class="control"><label for="noise">{t('Desviación estándar','Standard deviation',lang)}: <output id="noise-value" for="noise">15</output></label><input id="noise" type="range" min="5" max="40" step="1" value="15"></div><p class="demo-note">{t('Dos grupos independientes del mismo tamaño, igual desviación estándar y aproximación normal.','Two independent groups of equal size, equal standard deviations and a normal approximation.',lang)}</p></div><div><svg class="demo-chart" viewBox="0 0 500 230" role="img" aria-labelledby="chart-title"><title id="chart-title">{t('Estimación e intervalo aproximado','Estimate and approximate interval',lang)}</title><line x1="30" y1="150" x2="470" y2="150" stroke="#b1c5d2"/><line x1="250" y1="35" x2="250" y2="165" stroke="#8ca7b8" stroke-dasharray="5 5"/><text x="250" y="190" text-anchor="middle">0</text><text id="ci-negative" x="50" y="190" text-anchor="middle">−20</text><text id="ci-positive" x="450" y="190" text-anchor="middle">+20</text><line id="ci-line" x1="250" y1="110" x2="300" y2="110" stroke="#177b79" stroke-width="7" stroke-linecap="round"/><circle id="point" cx="275" cy="110" r="9" fill="#102b44"/><text x="250" y="216" text-anchor="middle">{t('Diferencia entre grupos (puntos)','Between-group difference (points)',lang)}</text></svg><div class="demo-results" role="status" aria-live="polite"><strong id="estimate">3</strong><span>{t('Intervalo aproximado del 95%','Approximate 95% interval',lang)}: <span id="interval"></span></span><p id="interpretation"></p></div></div></div><noscript><p class="no-js">{t('Activa JavaScript para utilizar los controles. El material descargable sigue disponible debajo.','Enable JavaScript to use the controls. Downloadable materials remain available below.',lang)}</p></noscript><details><summary>{t('Supuestos y cálculo','Assumptions and calculation',lang)}</summary><p>SE = √(2 × SD² / n). IC ≈ Δ ± 1,96 × SE.</p><p>{t('El ejemplo mantiene fija una diferencia observada y compara cómo cambia su intervalo al modificar n y SD. No genera muestras, no demuestra causalidad y no incorpora costes, sesgos de selección ni dependencias entre observaciones.','The example holds an observed difference fixed and compares how its interval changes with n and SD. It does not generate samples, establish causality or account for costs, selection bias or dependencies between observations.',lang)}</p></details></div></section><section class="section tint"><div class="wrap"><h2>{t('Aprender con código y materiales abiertos.','Learn with open code and materials.',lang)}</h2><div class="software-list">{''.join('<article><h3>'+esc(loc(p['title'],lang))+'</h3><p>'+esc(loc(p['description'],lang))+'</p>'+link('https://github.com/Teoriadejuego/'+p['repo'],t('Explorar el repositorio →','Explore the repository →',lang))+'</article>' for p in SOFTWARE if p['repo'] in ['aero_risk','arquitectura-datos-python-ciencia-abierta','miniweb-kikibouba','escaperoom'])}</div></div></section><section class="section"><div class="wrap"><h2>{t('Materiales en el repositorio institucional.','Materials in the institutional repository.',lang)}</h2><p>{t('Tareas, cuestionarios e instrucciones con autoría y procedencia en las fichas de Loyola. Son recursos docentes o de investigación, no pruebas comerciales de selección.','Tasks, questionnaires and instructions with authorship and provenance in Loyola records. These are teaching or research resources, not commercial recruitment tests.',lang)}</p><ul class="resource-list">{resources}</ul></div></section>'''
 shell(lang,'lab/',t('Laboratorio de Antonio Alfonso | Experimentos y recursos abiertos','Antonio Alfonso’s lab | Experiments and open resources',lang),t('Demostración interactiva de incertidumbre estadística, cuadernos Python y materiales institucionales abiertos de economía experimental.','Interactive statistical-uncertainty demonstration, Python notebooks and open institutional materials in experimental economics.',lang),body,'lab/')

def privacy(lang):
 body=f'''<section class="section"><div class="wrap privacy"><h1>{t('Privacidad y créditos.','Privacy and credits.',lang)}</h1><h2>{t('Una web sin seguimiento propio','No first-party tracking',lang)}</h2><p>{t('Esta web no incorpora analítica, cookies propias, formularios ni seguimiento publicitario. La búsqueda y la demostración se ejecutan en tu navegador. GitHub Pages recibe las solicitudes técnicas habituales de navegación.','This website has no analytics, first-party cookies, forms or advertising tracking. Search and the demonstration run in your browser. GitHub Pages receives normal technical navigation requests.',lang)}</p><h2>{t('Enlaces y contacto','Links and contact',lang)}</h2><p>{t('Los artículos, repositorios y demostraciones externas tienen sus propias condiciones. El enlace de correo abre tu aplicación de email. No se envía ningún mensaje automáticamente.','External articles, repositories and demonstrations have their own terms. The email link opens your email application. No message is sent automatically.',lang)}</p><h2>{t('Contenido e imágenes','Content and images',lang)}</h2><p>{t('Los resultados científicos pertenecen a sus equipos de autoría y se enlazan a sus fuentes. La ilustración de cabecera se ha generado para esta web. El retrato parte de una fotografía facilitada por Antonio Alfonso y se ha editado para renovar el fondo y la iluminación.','Scientific findings belong to their author teams and are linked to their sources. The header illustration was generated for this website. The portrait is based on a photograph supplied by Antonio Alfonso, edited to renew the background and lighting.',lang)}</p><p>{t('La selección de trabajos destaca alcance y relevancia aplicada; no constituye una clasificación de citas. Los diagramas del portfolio son esquemas explicativos.','The work selection highlights scope and applied relevance; it is not a citation ranking. Portfolio diagrams are explanatory schematics.',lang)}</p><p>Contacto: {link('mailto:aalfonsoc@gmail.com','aalfonsoc@gmail.com')}</p></div></section>'''
 shell(lang,'privacy/',t('Privacidad y créditos | Antonio Alfonso','Privacy and credits | Antonio Alfonso',lang),t('Información sobre privacidad, fuentes y créditos de la web profesional de Antonio Alfonso.','Privacy, sources and credits for Antonio Alfonso’s professional website.',lang),body,navkey='privacy/')

for lang in ['es','en']:
 home(lang);projects_page(lang);publication_page(lang);profile(lang);lab_page(lang);privacy(lang)
