(OUT/'.nojekyll').touch()
(OUT/'404.html').write_text(f'<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Página no encontrada | Antonio Alfonso</title><body style="font-family:system-ui;max-width:650px;margin:10vh auto;padding:25px"><h1>Esta página no está aquí.</h1><p>Puedes volver al portfolio para consultar proyectos, artículos y recursos.</p><a href="{BASE}/">Volver al inicio / Return home</a></body></html>',encoding='utf8')
print(f'Built {len(pages)} bilingual pages in {OUT}')
